    if not is_valid(*start) or not is_valid(*goal):
        return []
    if start == goal:
        return [start]

    from collections import deque

    def get_neighbors(cell):
        r, c = cell
        neighbors = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                neighbors.append( (nr, nc) )
        return neighbors

    parents_forward = {start: None}
    parents_backward = {goal: None}
    queue_forward = deque([start])
    queue_backward = deque([goal])

    def process_level(queue, parents, opposite_parents):
        for _ in range(len(queue)):
            current = queue.popleft()
            for neighbor in get_neighbors(current):
                if neighbor not in parents:
                    parents[neighbor] = current
                    queue.append(neighbor)
                    if neighbor in opposite_parents:
                        return neighbor
        return None

    while queue_forward and queue_backward:
        meeting = process_level(queue_forward, parents_forward, parents_backward)
        if meeting:
            path_start = []
            current = meeting
            while current is not None:
                path_start.append(current)
                current = parents_forward[current]
            path_start.reverse()
            path_end = []
            current = meeting
            while current is not None:
                path_end.append(current)
                current = parents_backward[current]
            return path_start + path_end[1:]
        meeting = process_level(queue_backward, parents_backward, parents_forward)
        if meeting:
